    obj_from_bm('Curtains', bm, MAT['curtain'], C, smooth=True)
    bm = bmesh.new()
    add_box(bm, x0 + 0.02, y0 + 5.3, z0 + 0.75, x0 + 0.62, y0 + 6.6, z0 + 0.78, mi=0)       # desk under the poster
    for (ya, yb) in ((y0 + 5.35, y0 + 5.42), (y0 + 6.48, y0 + 6.55)):
        add_box(bm, x0 + 0.05, ya, z0, x0 + 0.6, yb, z0 + 0.75, mi=0)
    for k in range(9):
        add_box(bm, x0 + 0.12, y0 + 5.5 + k * 0.05, z0 + 0.78, x0 + 0.34, y0 + 5.54 + k * 0.05, z0 + 1.05 + 0.04 * (k % 3), mi=1 + k % 3)
    obj_from_bm('Desk', bm, [MAT['wood_light'], MAT['book0'], MAT['book1'], MAT['book2']], C)
    # --- kitchen: counter + cabinets along the west wall, fridge, table + two chairs, pendant lamp
    bm = bmesh.new()
    add_box(bm, x0, y0 + 0.65, z0, x0 + 0.62, -35.25, z0 + 0.88, mi=0)
    add_box(bm, x0, y0 + 0.65, z0 + 0.88, x0 + 0.65, -35.25, z0 + 0.92, mi=1)
    add_box(bm, x0, y0 + 0.65, z0 + 1.5, x0 + 0.36, -35.25, z0 + 2.2, mi=0)
    add_box(bm, x0, y0 + 0.02, z0, x0 + 0.66, y0 + 0.64, z0 + 1.9, mi=2)                   # fridge
    add_box(bm, x0 + 0.66, y0 + 0.08, z0 + 1.1, x0 + 0.68, y0 + 0.11, z0 + 1.6, mi=3)
    add_cyl(bm, 0.2, 0.2, 0.01, seg=16, matrix=Matrix.Translation((x0 + 0.33, y0 + 2.4, z0 + 0.925)), mi=3)   # hob ring
    add_box(bm, x0 + 0.15, y0 + 1.4, z0 + 0.93, x0 + 0.5, y0 + 1.9, z0 + 0.95, mi=3)      # sink
    obj_from_bm('Kitchen', bm, [MAT['cabinet'], MAT['worktop'], MAT['fridge'], MAT['steel']], C)
    TX, TY = x1 - 1.35, -37.8
    bm = bmesh.new()
    add_box(bm, TX - 0.45, TY - 0.45, z0 + 0.72, TX + 0.45, TY + 0.45, z0 + 0.76, mi=0)
    for cx in (-0.38, 0.38):
        for cy in (-0.38, 0.38):
            add_box(bm, TX + cx - 0.025, TY + cy - 0.025, z0, TX + cx + 0.025, TY + cy + 0.025, z0 + 0.72, mi=0)
    obj_from_bm('KTable', bm, [MAT['wood_light']], C)
    bm = bmesh.new()
    cafe_chair(bm, (0, 0, 0))
    for k, (cx, cy, yaw) in enumerate(((TX - 0.62, TY, -90), (TX + 0.5, TY + 0.62, 160))):
        ob = obj_from_bm(f'KChair{k}', bm.copy(), [MAT['chair_wood'], MAT['chair_wood']], C, smooth=True)
        ob.location = (cx, cy, z0)
        ob.rotation_euler = (0, 0, R(yaw))
    bm.free()
    bm = bmesh.new()
    add_cyl(bm, 0.005, 0.005, 1.0, seg=6, matrix=Matrix.Translation((TX, TY, z1 - 0.5)), mi=0)
    add_cyl(bm, 0.2, 0.05, 0.18, seg=20, matrix=Matrix.Translation((TX, TY, z1 - 1.05)), mi=1, caps=False)
    obj_from_bm('Pendant', bm, [MAT['darksteel'], MAT['pendant_shade']], C, smooth=True)
    bm = bmesh.new()
    add_sphere(bm, 0.05, 12, 8, Matrix.Translation((TX, TY, z1 - 1.12)))
