# lit-window schedule for the outage (district -> time it goes dark in the "dark" shot)
OUTAGE = {6: 29.1, 5: 29.55, 4: 30.05, 12: 30.3, 1: 30.75, 2: 31.25}
LIT_NIGHT = {0: 1.0, 3: 0.75}


def lit_level(d, t, shot):
    """How many windows / street lamps of power district d are lit (0..1) at time t."""
    if shot in ('grid',):
        return 0.15 + 0.85 * ramp(t, 26.2, 28.6)
    if shot == 'dark':
        if d in OUTAGE:
            to = OUTAGE[d]
            if t < to:
                return 1.0
            fl = 0.5 + 0.5 * math.sin((t - to) * 70.0)
            return fl * (1 - lin(t, to, to + 0.22))
        return 1.0 if d in (0, 3) else 0.0
    if shot in ('kitchen', 'papers', 'playground', 'towers', 'house'):
        return LIT_NIGHT.get(d, 0.0)
    return 0.0


def update_world(t, shot):
    """Things that keep running on their own: signals, hazards, fountain, screens, escalator; window lights."""
    for d in range(ND):
        v = lit_level(d, t, shot)
        for s in SHOTVAL.get(f'lit{d}', []):
            s.default_value = v
        for s in SHOTVAL.get(f'lamp{d}', []):
            s.default_value = v * 18.0
    hz = 1.0 if (t * 1.5) % 1.0 < 0.5 else 0.0
    for s in SHOTVAL.get('hazard', []):
        s.default_value = 9.0 * hz
    # traffic signals: the hero head follows the story; the others cycle on their own
    sigs = STREET['signals']
    if shot == 'signal':
        set_signal(sigs[0], signal_state(t))
        set_signal(sigs[1], signal_state(t))
    else:
        cyc = (t % 20.0)
        st = 'green' if cyc < 8 else ('amber' if cyc < 10 else 'red')
        set_signal(sigs[0], st)
        set_signal(sigs[1], st)
    cross = 'red' if sigs[0]['lenses'][2].data.materials[0] == MAT['sig_green_on'] else 'green'
    for k in (2, 3, 4):
        set_signal(sigs[k], cross if k == 3 else ('green' if sigs[0]['lenses'][2].data.materials[0] == MAT['sig_green_on'] else 'red'))
    if shot in ('square',):
        P, r = fountain_droplets(t)
        set_points(WATER['drops'], P, r)
    elif WATER.get('active', True):
        set_points(WATER['drops'], np.zeros((0, 3)), np.zeros(0))
    WATER['active'] = shot == 'square'
    if shot == 'square':
        update_birds(t)
    if shot == 'papers':
        update_papers(t)
    if shot in ('playground',):
        update_swings(t, sit=True)
    if shot == 'mall':
        update_escalator(t)
    if shot == 'cinema':
        fl = 0.8 + 0.12 * math.sin(t * 7.3) + 0.08 * math.sin(t * 17.9 + 1.0)
        STREET['screen_light'].data.energy = 300.0 * fl
        for s in SHOTVAL.get('screen', []):
            s.default_value = 2.2 * fl
    if shot == 'house':
        fl = 0.75 + 0.2 * math.sin(t * 5.1) + 0.1 * math.sin(t * 13.7 + 2.0)
        STREET['tv_light'].data.energy = 25.0 * fl
        for s in SHOTVAL.get('tvglow', []):
            s.default_value = 1.6 * fl
    if shot == 'roofdoor':
        STREET['roofdoor'].rotation_euler = (0, 0, R(-105 * ramp(t, 42.45, 42.95)))
    else:
        STREET['roofdoor'].rotation_euler = (0, 0, 0)


CHOR = {
    'eyes': chor_bed, 'phone': chor_bed, 'window': chor_window, 'road': chor_road, 'market': chor_market, 'cinema': chor_cinema,
    'mall': chor_mall, 'square': chor_square, 'signal': chor_signal, 'station': chor_station, 'house': chor_house,
    'grid': None, 'dark': chor_window_dark, 'kitchen': chor_kitchen, 'papers': chor_papers, 'playground': chor_playground,
    'towers': chor_towers, 'roofdoor': chor_roofdoor, 'aerial': chor_parapet, 'edge': chor_parapet,
    'phone2': chor_phone_end, 'pocket': chor_phone_end, 'eyes2': chor_phone_end,
}
PROP_OF = {'eyes': ['phone'], 'phone': ['phone'], 'market': ['apple'], 'cinema': ['popcorn'], 'kitchen': ['photo'],
           'phone2': ['phone'], 'pocket': ['phone']}


def animate(t, shot):
    for k in ('phone', 'apple', 'photo', 'popcorn'):
        if k not in PROP_OF.get(shot, []):
            hide_prop(k)
    STREET['l_phone'].data.energy = 0.0
    fn = CHOR.get(shot)
    if fn is None:
        park(YOU)
    else:
        fn(t, shot)
    if shot in ('eyes', 'phone'):
        ph = FX['phone']
        STREET['l_phone'].location = ph.location + (eyes_mid() - ph.location).normalized() * 0.02
        STREET['l_phone'].rotation_euler = (eyes_mid() - ph.location).to_track_quat('-Z', 'Y').to_euler()
        STREET['l_phone'].data.energy = 3.0
    update_world(t, shot)

