FACS = {  # name: wall colour, glass colour, bay width, floor height
    'facade0': ((0.46, 0.36, 0.28), (0.10, 0.13, 0.16), 3.0, 3.4), 'facade1': ((0.66, 0.62, 0.55), (0.12, 0.15, 0.18), 2.6, 3.5),
    'facade2': ((0.38, 0.17, 0.12), (0.09, 0.11, 0.14), 2.4, 3.2), 'facade3': ((0.30, 0.33, 0.36), (0.16, 0.22, 0.28), 1.8, 3.4),
    'facade4': ((0.74, 0.70, 0.62), (0.11, 0.14, 0.17), 3.2, 3.3), 'facade_far': ((0.55, 0.55, 0.57), (0.20, 0.25, 0.30), 2.2, 3.5),
    'facade_glass': ((0.20, 0.24, 0.28), (0.18, 0.26, 0.34), 1.5, 3.8), 'facade_home': ((0.58, 0.55, 0.50), (0.10, 0.13, 0.16), 2.8, 3.0),
}


def city_facade_lit(name, wall, glass, cw, rh, key):
    """Window grid: one window per bay per floor, with sills, per-window tint and blinds; a share of the windows
    glows at night (strength from the Value node `key`, animated per power district)."""
    m, nt, out = new_mat(name)
    oc = nd(nt, 'ShaderNodeTexCoord').outputs['Object']
    s_ = sep(nt, oc)
    h = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    z = s_.outputs['Z']
    u = mth(nt, 'FRACT', mth(nt, 'DIVIDE', h, cw))
    v = mth(nt, 'FRACT', mth(nt, 'DIVIDE', z, rh))
    win = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', u, 0.18), mth(nt, 'LESS_THAN', u, 0.82)),
              mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', v, 0.28), mth(nt, 'LESS_THAN', v, 0.86)))
    sill = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', u, 0.14), mth(nt, 'LESS_THAN', u, 0.86)),
               mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', v, 0.24), mth(nt, 'LESS_THAN', v, 0.28)))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', h, cw)), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, rh)), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell)
    rnd = wn.outputs['Value']
    rcol = wn.outputs['Color']
    blind = mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', v, mth(nt, 'MULTIPLY_ADD', rnd, -0.5, 0.95)), mth(nt, 'GREATER_THAN', rnd, 0.45))
    gcol = mixc(nt, mth(nt, 'MULTIPLY', rnd, 0.7), rgba(glass), rgba([min(1, c * 1.8) for c in glass]))
    gcol = mixc(nt, blind, gcol, (0.70, 0.66, 0.58, 1))
    n = noise(nt, 0.35, 3.0, 0.55, vec=oc)
    wcol = mixc(nt, mth(nt, 'MULTIPLY', n, 0.45), rgba(wall), rgba([c * 0.72 for c in wall]))
    wcol = mixc(nt, sill, wcol, (0.78, 0.76, 0.72, 1))
    col = mixc(nt, win, wcol, gcol)
    rough = mth(nt, 'ADD', mth(nt, 'MULTIPLY', win, -0.72), 0.82)
    p = principled(nt, out, **{'Base Color': col, 'Roughness': rough, 'Specular IOR Level': mth(nt, 'ADD', mth(nt, 'MULTIPLY', win, 0.5), 0.35)})
    # lit windows: ~38 % of them, warm or cool, some dimmer
    r2 = sep(nt, rcol).outputs['X']
    on = mth(nt, 'MULTIPLY', win, mth(nt, 'GREATER_THAN', r2, 0.62))
    warm = mixc(nt, mth(nt, 'GREATER_THAN', sep(nt, rcol).outputs['Y'], 0.8), (1.0, 0.68, 0.36, 1), (0.75, 0.85, 1.0, 1))
    nt.links.new(warm, p.inputs['Emission Color'])
    lvl = value(nt, key, 0.0)
    nt.links.new(mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', on, lvl), mth(nt, 'MULTIPLY_ADD', sep(nt, rcol).outputs['Z'], 1.3, 0.5)),
                 p.inputs['Emission Strength'])
    MAT[name] = m
    register_value(m, key, key)
    return m


def fmat(fac, d):
    nm = f'{fac}_d{d}'
    if nm not in MAT:
        wall, glass, cw, rh = FACS[fac]
        city_facade_lit(nm, wall, glass, cw, rh, f'lit{d}')
    return MAT[nm]


def glow_image_mat(name, tex, key, strength):
    m, nt, out = new_mat(name)
    t = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND')
    e = nd(nt, 'ShaderNodeEmission', Color=t.outputs['Color'], Strength=value(nt, key, strength))
    nt.links.new(e.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    register_value(m, key, key)


def lamp_mat(name, key):
    m, nt, out = new_mat(name)
    principled(nt, out, **{'Base Color': (0.92, 0.9, 0.84, 1), 'Roughness': 0.25, 'Emission Color': (1.0, 0.76, 0.45, 1),
                           'Emission Strength': value(nt, key, 0.0)})
    MAT[name] = m
    register_value(m, key, key)


def glass_window_material():
    m, nt, out = new_mat('window_glass')
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.25)
    tp = nd(nt, 'ShaderNodeBsdfTransparent', Color=(0.96, 0.98, 0.98, 1))
    gl = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.02)
    mx = nd(nt, 'ShaderNodeMixShader', Fac=mth(nt, 'MULTIPLY_ADD', lw.outputs['Fresnel'], 0.6, 0.04))
    nt.links.new(tp.outputs[0], mx.inputs[1])
    nt.links.new(gl.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT['window_glass'] = m


def beam_material():
    m, nt, out = new_mat('beam')
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.5)
    f = mth(nt, 'POWER', lw.outputs['Facing'], 2.5)
    n = noise(nt, 1.2, 4.0, 0.6, vec=obj_coord(nt))
    e = nd(nt, 'ShaderNodeEmission', Color=(0.85, 0.82, 0.75, 1), Strength=mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', f, 0.18),
                                                                                  mth(nt, 'MULTIPLY_ADD', n, 1.2, 0.3)))
    tr = nd(nt, 'ShaderNodeBsdfTransparent')
    ad = nd(nt, 'ShaderNodeAddShader')
    nt.links.new(e.outputs[0], ad.inputs[0])
    nt.links.new(tr.outputs[0], ad.inputs[1])
    nt.links.new(ad.outputs[0], out.inputs['Surface'])
    MAT['beam'] = m


