    b2 = mth(nt, 'FRACT', mth(nt, 'MULTIPLY', mth(nt, 'ADD', uv.outputs['Y'], uv.outputs['Z']), 28.0))
    wire = mth(nt, 'MAXIMUM', mth(nt, 'LESS_THAN', a, 0.18), mth(nt, 'LESS_THAN', b2, 0.18))
    p = principled(nt, None, **{'Base Color': (0.7, 0.72, 0.74, 1), 'Metallic': 0.9, 'Roughness': 0.3})
